INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4589566, 661639, 811, '<td valign="top">This is cool.  I like it.  Don''t know WHY I like it, I just do.  The people barely in the frame really make it work well.</td>', 'This is cool.  I like it.  Don''t know WHY I like it, I just do.  The people barely in the frame really make it work well.', '2008-03-26 16:45:26.000000', NULL, 1),
(4589567, 661955, 30982, '<td valign="top">I like the surprise of the guy in the red shirt.  Neat against all that blue and green.</td>', 'I like the surprise of the guy in the red shirt.  Neat against all that blue and green.', '2008-03-26 16:46:17.000000', NULL, 1),
(4589568, 662151, 811, '<td valign="top">I like how the colors *don''t* contrast, but it seems a bit oversharpened in some places.  I also like how the light "falls" off</td>', 'I like how the colors *don''t* contrast, but it seems a bit oversharpened in some places.  I also like how the light "falls" off', '2008-03-26 16:46:18.000000', NULL, 1),
(4589570, 662250, 811, '<td valign="top">cool colors.  nice abstract.</td>', 'cool colors.  nice abstract.', '2008-03-26 16:47:20.000000', NULL, 1),
(4589571, 662118, 30982, '<td valign="top">Very clean, very crisp - would make an excellent stock shot.</td>', 'Very clean, very crisp - would make an excellent stock shot.', '2008-03-26 16:47:22.000000', NULL, 1),
(4589572, 662090, 811, '<td valign="top">very "classic"  I love the level of contrast and tones in this --excellent bw.</td>', 'very "classic"  I love the level of contrast and tones in this --excellent bw.', '2008-03-26 16:47:49.000000', NULL, 1),
(4589573, 660880, 811, '<td valign="top">Excellent!</td>', 'Excellent!', '2008-03-26 16:48:17.000000', NULL, 1),
(4589574, 661806, 30982, '<td valign="top">A Mazda headlight?  Really does have an interesting pattern to it.</td>', 'A Mazda headlight?  Really does have an interesting pattern to it.', '2008-03-26 16:48:25.000000', NULL, 1),
(4589578, 662086, 811, '<td valign="top">Good use of the peanut to "break up" the repetition and add interest.  Great detail</td>', 'Good use of the peanut to "break up" the repetition and add interest.  Great detail', '2008-03-26 16:50:18.000000', NULL, 1),
(4589580, 662222, 811, '<td valign="top">Very impressionistic.  I like the extreme shallow dof and the little burst of color in the background is a nice contrast.  I find myself wanting to push apart whatever that is and see what the purple is.<br/> <br/>It''s a nice shot.  Hope the voters don''t chew you up too badly. :)</td>', 'Very impressionistic.  I like the extreme shallow dof and the little burst of color in the background is a nice contrast.  I find myself wanting to push apart whatever that is and see what the purple is. It''s a nice shot.  Hope the voters don''t chew you up too badly. :)', '2008-03-26 16:52:36.000000', NULL, 1),
(4589581, 661902, 811, '<td valign="top">nice contrast</td>', 'nice contrast', '2008-03-26 16:53:41.000000', NULL, 1),
(4589583, 660405, 811, '<td valign="top">that''s some bright colors!</td>', 'that''s some bright colors!', '2008-03-26 16:54:15.000000', NULL, 1),
(4589588, 661923, 811, '<td valign="top">I like how everything -- composition, lighting, etc. forces the eyes to the light</td>', 'I like how everything -- composition, lighting, etc. forces the eyes to the light', '2008-03-26 16:54:56.000000', NULL, 1),
(4589591, 661354, 811, '<td valign="top">I like how the green peeks out from behind the red.  Great color contrasts.   There is focus there, it just isn''t obvious.  Hope this doesn''t get too mangled by the voters, it really is nice.  :)</td>', 'I like how the green peeks out from behind the red.  Great color contrasts.   There is focus there, it just isn''t obvious.  Hope this doesn''t get too mangled by the voters, it really is nice.  :)', '2008-03-26 16:56:03.000000', NULL, 1),
(4589598, 661325, 811, '<td valign="top">What is really cool is that I have to scroll to see the whole thing (crappy sized work monitors) and when you scroll this one up and down really fast, it will mess with your eyes. :)</td>', 'What is really cool is that I have to scroll to see the whole thing (crappy sized work monitors) and when you scroll this one up and down really fast, it will mess with your eyes. :)', '2008-03-26 16:58:48.000000', NULL, 1),
