(4589611, 660667, 30982, '<td valign="top">Great response to the challenge.</td>', 'Great response to the challenge.', '2008-03-26 17:02:44.000000', NULL, 1),
(4589612, 660880, 30982, '<td valign="top">This wouldn''t work as well for me without the person there.  Very nice light for this shot, and perfect for B&amp;W.</td>', 'This wouldn''t work as well for me without the person there.  Very nice light for this shot, and perfect for B&W.', '2008-03-26 17:03:08.000000', NULL, 1),
