INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4592538, 662160, 83080, '<td valign="top">Beautiful scrolling/curving pattern and I really love the color.  It''s fascinating watching smoke curl like this.</td>', 'Beautiful scrolling/curving pattern and I really love the color.  It''s fascinating watching smoke curl like this.', '2008-03-27 22:15:40.000000', NULL, 1),
(4592539, 661598, 66041, '<td valign="top">oh man.   really hot photo - but a pattern???</td>', 'oh man.   really hot photo - but a pattern???', '2008-03-27 22:15:47.000000', NULL, 1),
(4592551, 661906, 91131, '<td valign="top">nice</td>', 'nice', '2008-03-27 22:24:27.000000', NULL, 1),
(4592553, 662137, 7778, '<td valign="top">Energy/Range/Story: 7/5/3 <br/>Composition/perspective/manner: 7/7/8 <br/>Aesthetics/Technical: 6/7 <br/>Presentation: 6 <br/>Total: 6.2 <br/>Vote: 6 <br/> <br/>Remarks: Variation is a wonderful thing when repetition is the theme. Here it just <i>flows</i> conically in- or declining, through the frame. What''s striking is that the pattern is forever changing while maintaining a constant of shape and line (I suspect the foreground green outlines a curve too large to be contained by the margins).<br/> <br/>The diagonal perspective is dynamically placed, too, against a measured rhythm of rush and recess. The (apparent} bouquet suggests a similar progression, sans the plastic relief of the fore- and middle grounds.<br/> <br/>I converted the image to black and white (gradient map) to see if the colours provided a critical element. My impression was that it held its own, albeit intrinsically like cello in a jazz quartett. It did, however, loose the contemporary sense of the colour version.</td>', 'Energy/Range/Story: 7/5/3 Composition/perspective/manner: 7/7/8 Aesthetics/Technical: 6/7 Presentation: 6 Total: 6.2 Vote: 6  Remarks: Variation is a wonderful thing when repetition is the theme. Here it just flows conically in- or declining, through the frame. What''s striking is that the pattern is forever changing while maintaining a constant of shape and line (I suspect the foreground green outlines a curve too large to be contained by the margins). The diagonal perspective is dynamically placed, too, against a measured rhythm of rush and recess. The (apparent} bouquet suggests a similar progression, sans the plastic relief of the fore- and middle grounds. I converted the image to black and white (gradient map) to see if the colours provided a critical element. My impression was that it held its own, albeit intrinsically like cello in a jazz quartett. It did, however, loose the contemporary sense of the colour version.', '2008-03-27 22:25:41.000000', NULL, 1),
(4592554, 661963, 91131, '<td valign="top">nice</td>', 'nice', '2008-03-27 22:25:48.000000', NULL, 1),
(4592558, 660547, 34255, '<td valign="top">Interesting image, needs a title that does it justice.</td>', 'Interesting image, needs a title that does it justice.', '2008-03-27 22:28:48.000000', NULL, 1),
