(4595079, 661011, 79955, '<td valign="top">I feel that in basic editing, shots like yours are very difficult to post process. I would have preferred more detail in the bright areas. The longer you look at the image the more interesting it becomes. 6 , good luck with the voters</td>', 'I feel that in basic editing, shots like yours are very difficult to post process. I would have preferred more detail in the bright areas. The longer you look at the image the more interesting it becomes. 6 , good luck with the voters', '2008-03-29 08:12:44.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4595081, 662119, 79955, '<td valign="top">I am puzzled how you created this in basic editing. Anyway I will rate it without considering how you post processed it. 7 , I really like the image.</td>', 'I am puzzled how you created this in basic editing. Anyway I will rate it without considering how you post processed it. 7 , I really like the image.', '2008-03-29 08:13:52.000000', NULL, 1),
(4595083, 660125, 83313, '<td valign="top">I like the viewpoint and you caught some great lighting and visual appeal in a common thing.<br/> <br/>I do have a fuss that is keeping me from giving it a high end score, though. You have lost lots of clarity and detail to JPEG compression. Your file size is only 56k, when you had up to 150k to use for this challenge. I noticed it first in the pipe on the upper left, but it can be seen in other details as well. Check the JPEG compression settings in your image editor and always try to save as close to the limit for a challenge as you can get it without going over.</td>', 'I like the viewpoint and you caught some great lighting and visual appeal in a common thing. I do have a fuss that is keeping me from giving it a high end score, though. You have lost lots of clarity and detail to JPEG compression. Your file size is only 56k, when you had up to 150k to use for this challenge. I noticed it first in the pipe on the upper left, but it can be seen in other details as well. Check the JPEG compression settings in your image editor and always try to save as close to the limit for a challenge as you can get it without going over.', '2008-03-29 08:15:51.000000', NULL, 1),
(4595084, 660349, 79955, '<td valign="top">Interesting how the shade of the tiles changes. IMO overall image is too "flat" not "3d" like if you get what I mean.<br/>Try shooting from different angles &amp; with different crops , to get something more interesting.</td>', 'Interesting how the shade of the tiles changes. IMO overall image is too "flat" not "3d" like if you get what I mean.Try shooting from different angles & with different crops , to get something more interesting.', '2008-03-29 08:16:55.000000', NULL, 1),
(4595086, 660602, 55838, '<td valign="top">I like this different pattern.  A fun real life shot that is perfect for the challenge.  Well done!</td>', 'I like this different pattern.  A fun real life shot that is perfect for the challenge.  Well done!', '2008-03-29 08:17:26.000000', NULL, 1),
(4595087, 662086, 83313, '<td valign="top">Very nice macro of these. I like the details and rich color showing. DOF is nearly perfect.</td>', 'Very nice macro of these. I like the details and rich color showing. DOF is nearly perfect.', '2008-03-29 08:17:56.000000', NULL, 1),
(4595088, 660120, 79955, '<td valign="top">Unfortunately at your point of focus, the focus is still too soft. Image needs to have more DOF &amp; crisper focus to have more impact. Overall composition is good.</td>', 'Unfortunately at your point of focus, the focus is still too soft. Image needs to have more DOF & crisper focus to have more impact. Overall composition is good.', '2008-03-29 08:18:22.000000', NULL, 1),
(4595090, 661192, 79955, '<td valign="top">Interesting !! The patterns unfortunately do not "wow" me sufficiently</td>', 'Interesting !! The patterns unfortunately do not "wow" me sufficiently', '2008-03-29 08:20:08.000000', NULL, 1),
(4595094, 661815, 79955, '<td valign="top">Interesting interpretation, like the color hues &amp; saturation. 6</td>', 'Interesting interpretation, like the color hues & saturation. 6', '2008-03-29 08:20:53.000000', NULL, 1),
(4595100, 660769, 79955, '<td valign="top">Very cool shot, I still listen to vinyl (much better than CD). Anyway good luck with the voters. 6</td>', 'Very cool shot, I still listen to vinyl (much better than CD). Anyway good luck with the voters. 6', '2008-03-29 08:23:07.000000', NULL, 1),
(4595104, 660120, 90849, '<td valign="top">Good idea, but I think the shot would be better if the aperture was reduced allowing a greater depth of field.  Also the focus should be done on the beginning of the fretboard, not in the middle.</td>', 'Good idea, but I think the shot would be better if the aperture was reduced allowing a greater depth of field.  Also the focus should be done on the beginning of the fretboard, not in the middle.', '2008-03-29 08:24:04.000000', NULL, 1),
(4595107, 662248, 79955, '<td valign="top">very good macro 6</td>', 'very good macro 6', '2008-03-29 08:25:01.000000', NULL, 1),
(4595111, 662160, 79955, '<td valign="top">Getting to be overdone like splashes, but still nice &amp; interesting to look at. Your version is one of the better ones that I prefer. nice work 7</td>', 'Getting to be overdone like splashes, but still nice & interesting to look at. Your version is one of the better ones that I prefer. nice work 7', '2008-03-29 08:26:16.000000', NULL, 1),
(4595114, 662137, 55838, '<td valign="top">Beautiful colors - in true DPC eye candy fashion.  Something in the slightly dark feel of this shot makes me think I might know whose it is.  Clearly the work of a true professional.  ; )  Back to bump you up to 9.</td>', 'Beautiful colors - in true DPC eye candy fashion.  Something in the slightly dark feel of this shot makes me think I might know whose it is.  Clearly the work of a true professional.  ; )  Back to bump you up to 9.', '2008-03-29 08:27:33.000000', NULL, 1),
(4595117, 661365, 55838, '<td valign="top">Such a great idea for the challenge and very nice color.  I think the perspective you chose was perfect.</td>', 'Such a great idea for the challenge and very nice color.  I think the perspective you chose was perfect.', '2008-03-29 08:28:51.000000', NULL, 1),
(4595119, 662169, 83313, '<td valign="top">Airport coin op units? A little color adjustment may have helped this have some more oomph.</td>', 'Airport coin op units? A little color adjustment may have helped this have some more oomph.', '2008-03-29 08:29:47.000000', NULL, 1),
(4595120, 661906, 55838, '<td valign="top">I find the b&amp;w treatment very pleasing on this shot.  Nice DOF too.  Back to bump you up to 8.</td>', 'I find the b&w treatment very pleasing on this shot.  Nice DOF too.  Back to bump you up to 8.', '2008-03-29 08:30:05.000000', NULL, 1),
(4595121, 662203, 83313, '<td valign="top">Not sure if I like the purpley tone or not, but I do think the monochrome brought out a lot of nice detail.</td>', 'Not sure if I like the purpley tone or not, but I do think the monochrome brought out a lot of nice detail.', '2008-03-29 08:31:14.000000', NULL, 1),
(4595123, 660363, 55838, '<td valign="top">Very nice paper pattern.  I like that some of the hearts are more dark and others lighter.  Back to bump you up to 8.</td>', 'Very nice paper pattern.  I like that some of the hearts are more dark and others lighter.  Back to bump you up to 8.', '2008-03-29 08:31:28.000000', NULL, 1),
(4595125, 660645, 83313, '<td valign="top">I''ll bet the details in the larger version of this are outstanding.</td>', 'I''ll bet the details in the larger version of this are outstanding.', '2008-03-29 08:32:41.000000', NULL, 1),
(4595126, 660634, 55838, '<td valign="top">Very nice shot of patterns.  Good flow and great in B&amp;W too.  Back to bump you up to 8.</td>', 'Very nice shot of patterns.  Good flow and great in B&W too.  Back to bump you up to 8.', '2008-03-29 08:33:03.000000', NULL, 1),
(4595127, 661623, 55838, '<td valign="top">Stunning color and interesting flow.  Cool perspective and simply a perfect title.  : )  Back to bump you up to 8.</td>', 'Stunning color and interesting flow.  Cool perspective and simply a perfect title.  : )  Back to bump you up to 8.', '2008-03-29 08:33:59.000000', NULL, 1),
(4595134, 662265, 83313, '<td valign="top">Nice vibrant reds and an appealing pattern. I think the focus point should have been a little closer, as my eye is being led toward the second red on in from the top left, which is slightly out of focus.</td>', 'Nice vibrant reds and an appealing pattern. I think the focus point should have been a little closer, as my eye is being led toward the second red on in from the top left, which is slightly out of focus.', '2008-03-29 08:35:36.000000', NULL, 1),
(4595135, 662250, 55838, '<td valign="top">Great colors with a cool graffiti sort of feel.  The colors are balanced well with the blacks &amp; grays up top - would have been too much without them.  Back to bump you up to 8.</td>', 'Great colors with a cool graffiti sort of feel.  The colors are balanced well with the blacks & grays up top - would have been too much without them.  Back to bump you up to 8.', '2008-03-29 08:36:05.000000', NULL, 1),
(4595138, 660880, 55838, '<td valign="top">Love the light and shadow here - gives the shot great dimension.  Of course the man adds something special too.  Back to bump you up to 8.</td>', 'Love the light and shadow here - gives the shot great dimension.  Of course the man adds something special too.  Back to bump you up to 8.', '2008-03-29 08:38:09.000000', NULL, 1),
(4595139, 661917, 83313, '<td valign="top">Nice. Very peaceful looking. Seems to have been caught in shadows. I''d suggest some adjustments to help bring out the details, but I suspect you have already done as much as you could without making it look unnatural.</td>', 'Nice. Very peaceful looking. Seems to have been caught in shadows. I''d suggest some adjustments to help bring out the details, but I suspect you have already done as much as you could without making it look unnatural.', '2008-03-29 08:38:22.000000', NULL, 1),
(4595141, 661598, 55838, '<td valign="top">Beautiful colors and clean simple composition.  Back to bump you up to 8.</td>', 'Beautiful colors and clean simple composition.  Back to bump you up to 8.', '2008-03-29 08:38:46.000000', NULL, 1),
(4595143, 661987, 55838, '<td valign="top">A great real life looking shot.  I can''t quite put my finger on why I like it - I just do!  Back to bump you up to 8.</td>', 'A great real life looking shot.  I can''t quite put my finger on why I like it - I just do!  Back to bump you up to 8.', '2008-03-29 08:39:47.000000', NULL, 1),
(4595146, 662177, 55838, '<td valign="top">Awwwww - such cute little patterns!</td>', 'Awwwww - such cute little patterns!', '2008-03-29 08:40:36.000000', NULL, 1),
(4595147, 661567, 83313, '<td valign="top">I like the pattern, but there is not as much detail showing as I would expect. Your vertical size is 100 pixels less than it could have been for this challenge. A full 640 pixels would have probably gotten a lot more detail in there.</td>', 'I like the pattern, but there is not as much detail showing as I would expect. Your vertical size is 100 pixels less than it could have been for this challenge. A full 640 pixels would have probably gotten a lot more detail in there.', '2008-03-29 08:40:41.000000', NULL, 1),
(4595149, 662072, 55838, '<td valign="top">Cool shot perfectly named.  Nice earthy color tones and great movement.  Back to bump up to 8.</td>', 'Cool shot perfectly named.  Nice earthy color tones and great movement.  Back to bump up to 8.', '2008-03-29 08:42:22.000000', NULL, 1),
(4595150, 661963, 83313, '<td valign="top">Great work. The backlighting shows it off nicely. Only minor issue is a bit of visible dust on the tabletop.</td>', 'Great work. The backlighting shows it off nicely. Only minor issue is a bit of visible dust on the tabletop.', '2008-03-29 08:42:41.000000', NULL, 1),
(4595154, 661639, 55838, '<td valign="top">I love the lines and shadows in this shot.  Good choice on the "half people".  Back to bump you up to 8.</td>', 'I love the lines and shadows in this shot.  Good choice on the "half people".  Back to bump you up to 8.', '2008-03-29 08:45:29.000000', NULL, 1),
(4595156, 660656, 55838, '<td valign="top">A very pleasing shot and a great idea.  Back to bump you up to 8.</td>', 'A very pleasing shot and a great idea.  Back to bump you up to 8.', '2008-03-29 08:46:21.000000', NULL, 1),
(4595160, 661920, 83080, '<td valign="top">Interesting pattern and I can''t make out what it is, so I hope you''ll clue us in at the end.  Your choice of angle makes for a very satisfying composition.</td>', 'Interesting pattern and I can''t make out what it is, so I hope you''ll clue us in at the end.  Your choice of angle makes for a very satisfying composition.', '2008-03-29 08:49:39.000000', NULL, 1),
(4595165, 662237, 83080, '<td valign="top">Very creative technique and I love the effect for this challenge.  I''m curious what this would have looked like if the focal plane were a little further back, possibly with greater DOF to allow the surface texture to come through on the curves.  Not sure it would result in an improvement, just curious.</td>', 'Very creative technique and I love the effect for this challenge.  I''m curious what this would have looked like if the focal plane were a little further back, possibly with greater DOF to allow the surface texture to come through on the curves.  Not sure it would result in an improvement, just curious.', '2008-03-29 08:58:38.000000', NULL, 1),
(4595201, 662084, 79955, '<td valign="top">Nice tones, nice color</td>', 'Nice tones, nice color', '2008-03-29 10:05:46.000000', NULL, 1),
(4595204, 660096, 79955, '<td valign="top">Very very nice , excellent color &amp; composition 8</td>', 'Very very nice , excellent color & composition 8', '2008-03-29 10:08:24.000000', NULL, 1),
(4595207, 661965, 79955, '<td valign="top">Very nice , very well composed 7</td>', 'Very nice , very well composed 7', '2008-03-29 10:10:04.000000', NULL, 1),
(4595211, 661391, 79955, '<td valign="top">Good composition, nice saturation 7</td>', 'Good composition, nice saturation 7', '2008-03-29 10:12:06.000000', NULL, 1),
(4595259, 661542, 70514, '<td valign="top">I like the contrasting colors, but it seems a bit noisy and not very sharp.</td>', 'I like the contrasting colors, but it seems a bit noisy and not very sharp.', '2008-03-29 10:37:53.000000', NULL, 1),
(4595261, 661611, 70514, '<td valign="top">Great dof.</td>', 'Great dof.', '2008-03-29 10:38:41.000000', NULL, 1),
(4595266, 662255, 70514, '<td valign="top">Seems to lack contrast and sharpness.</td>', 'Seems to lack contrast and sharpness.', '2008-03-29 10:40:26.000000', NULL, 1),
(4595268, 660076, 70514, '<td valign="top">This reminds me of drives to my Grandparent''s home in a very stark area of Kansas.  Lovely conversion and great lines.</td>', 'This reminds me of drives to my Grandparent''s home in a very stark area of Kansas.  Lovely conversion and great lines.', '2008-03-29 10:41:44.000000', NULL, 1),
(4595271, 660319, 70514, '<td valign="top">Great composition and perspective.  College days never looked so good.</td>', 'Great composition and perspective.  College days never looked so good.', '2008-03-29 10:43:17.000000', NULL, 1),
(4595282, 661368, 90658, '<td valign="top">The pattern here is probably more subtle than you think it is.  You are probably going to some lower scores because some aren''t going to see it, you may even get a few DNMC comments.  That being said,  I would crop this a bit more to "enhance" the pattern and make folks see it.</td>', 'The pattern here is probably more subtle than you think it is.  You are probably going to some lower scores because some aren''t going to see it, you may even get a few DNMC comments.  That being said,  I would crop this a bit more to "enhance" the pattern and make folks see it.', '2008-03-29 10:56:49.000000', NULL, 1),
(4595285, 662262, 90658, '<td valign="top">The "pattern" idea is being stretched a bit in this shot, imo.  But there is one, so yeah!  Nice choice on dof, with the red bean there, you might not have needed the effect, but at least it''s not overdone.</td>', 'The "pattern" idea is being stretched a bit in this shot, imo.  But there is one, so yeah!  Nice choice on dof, with the red bean there, you might not have needed the effect, but at least it''s not overdone.', '2008-03-29 10:58:55.000000', NULL, 1),
(4595288, 661959, 90658, '<td valign="top">I felt like I really had to stretch the idea of a "pattern" to it''s extreme.  I guess art is supposed to make you stretch, but sometimes forcing the viewer to think that hard is going to frustrate them.  As a picture, not in a challenge, I do like this.</td>', 'I felt like I really had to stretch the idea of a "pattern" to it''s extreme.  I guess art is supposed to make you stretch, but sometimes forcing the viewer to think that hard is going to frustrate them.  As a picture, not in a challenge, I do like this.', '2008-03-29 11:00:38.000000', NULL, 1),
(4595291, 661955, 90658, '<td valign="top">In my tastes, alone, I am not sure the reflections in the windows added anything to this shot.  However, I have a gut feeling that it was the reflections that drew you to this shot and you wanted them there.</td>', 'In my tastes, alone, I am not sure the reflections in the windows added anything to this shot.  However, I have a gut feeling that it was the reflections that drew you to this shot and you wanted them there.', '2008-03-29 11:03:04.000000', NULL, 1),
(4595292, 661975, 90658, '<td valign="top">Simple and elegant.  The reflection could or could not be there.  Either way, you lose or gain nothing...if that makes sense.  This shot would have been just as dramatic without the reflection.  But the reflection creates it''s own drama.  I know I''m not saying this well...forgive me.</td>', 'Simple and elegant.  The reflection could or could not be there.  Either way, you lose or gain nothing...if that makes sense.  This shot would have been just as dramatic without the reflection.  But the reflection creates it''s own drama.  I know I''m not saying this well...forgive me.', '2008-03-29 11:05:10.000000', NULL, 1),
(4595293, 662084, 90658, '<td valign="top">This seems a bit flat to me.  Perhaps it is just that all of the colors in the buildings are similar, so things blend in.  Not really your fault, but a different angle might have given some shading to add dimension.</td>', 'This seems a bit flat to me.  Perhaps it is just that all of the colors in the buildings are similar, so things blend in.  Not really your fault, but a different angle might have given some shading to add dimension.', '2008-03-29 11:06:23.000000', NULL, 1),
(4595299, 660941, 90658, '<td valign="top">The title of the challenge, Patterns, creates a pre-defined idea of what one would be looking at.  I have twisted and torked the definition of pattern in many ways, I stretched my paradigm hugely, and I don''t see it.  The fact that they are all chocolate Easter candies, is not really a pattern, it''s a reality.  The fact that one foil is around a candy that might not be entirely chocolate is just irony.  I think the colors are nice and it is relatively well designed shot, I just don''t see the pattern...not that it doesn''t exist.  That being said, you could create pattern in this with some work.  Line up the eggs so there is some type of order, keep the colors grouped in lines or shapes, repeat that throughout, and then throw the yellow one in.</td>', 'The title of the challenge, Patterns, creates a pre-defined idea of what one would be looking at.  I have twisted and torked the definition of pattern in many ways, I stretched my paradigm hugely, and I don''t see it.  The fact that they are all chocolate Easter candies, is not really a pattern, it''s a reality.  The fact that one foil is around a candy that might not be entirely chocolate is just irony.  I think the colors are nice and it is relatively well designed shot, I just don''t see the pattern...not that it doesn''t exist.  That being said, you could create pattern in this with some work.  Line up the eggs so there is some type of order, keep the colors grouped in lines or shapes, repeat that throughout, and then throw the yellow one in.', '2008-03-29 11:12:08.000000', NULL, 1),
(4595302, 661961, 90658, '<td valign="top">Just too dark.  I know, the shadows and light will be diminished by brightening things.  Tough position to be in.  This probably just comes down to taste.</td>', 'Just too dark.  I know, the shadows and light will be diminished by brightening things.  Tough position to be in.  This probably just comes down to taste.', '2008-03-29 11:13:25.000000', NULL, 1),
(4595307, 662236, 90658, '<td valign="top">You actually have a lot going on here.  Pattern from the metal, pattern in the shadow, pattern of the wood grain.  The title infers that the metal is your subject.  My eyes are only drawn to the metal in the lower center area.  Was this a rounded subject?</td>', 'You actually have a lot going on here.  Pattern from the metal, pattern in the shadow, pattern of the wood grain.  The title infers that the metal is your subject.  My eyes are only drawn to the metal in the lower center area.  Was this a rounded subject?', '2008-03-29 11:16:10.000000', NULL, 1),
(4595308, 662185, 89547, '<td valign="top">I like the shape and form in volved in the picture.</td>', 'I like the shape and form in volved in the picture.', '2008-03-29 11:16:36.000000', NULL, 1),
(4595309, 660682, 89547, '<td valign="top">Nice light relfection on the surface, it gives it an 3-d appearance.</td>', 'Nice light relfection on the surface, it gives it an 3-d appearance.', '2008-03-29 11:17:28.000000', NULL, 1),
(4595310, 662222, 89547, '<td valign="top">Nice idea, good unique color, and lines which lead the eye.</td>', 'Nice idea, good unique color, and lines which lead the eye.', '2008-03-29 11:17:52.000000', NULL, 1),
(4595311, 660546, 90658, '<td valign="top">Getting a shot as clear as this through glass is wonderful, or do you have a fancy, shmancy underwater camera?  I do like this, I am just wondering if having your subject right in the center is the best presentation.</td>', 'Getting a shot as clear as this through glass is wonderful, or do you have a fancy, shmancy underwater camera?  I do like this, I am just wondering if having your subject right in the center is the best presentation.', '2008-03-29 11:17:57.000000', NULL, 1),
(4595312, 661631, 89547, '<td valign="top">Nice pattern with good detail of the wood''s pattern too. Nice line movement also.</td>', 'Nice pattern with good detail of the wood''s pattern too. Nice line movement also.', '2008-03-29 11:18:24.000000', NULL, 1),
(4595313, 660602, 89547, '<td valign="top">Great shadows and form/shape used in creating this photo.</td>', 'Great shadows and form/shape used in creating this photo.', '2008-03-29 11:18:49.000000', NULL, 1),
(4595314, 662208, 89547, '<td valign="top">Good texture of the picture, it looks as if you can feel the shell.</td>', 'Good texture of the picture, it looks as if you can feel the shell.', '2008-03-29 11:19:10.000000', NULL, 1),
