(4595325, 662089, 89547, '<td valign="top">great value and contrast coming from the wall and the branches, Great, one of the best i have seen(9). good movement created by the branches too.</td>', 'great value and contrast coming from the wall and the branches, Great, one of the best i have seen(9). good movement created by the branches too.', '2008-03-29 11:22:39.000000', NULL, 1),
(4595327, 661567, 89547, '<td valign="top">Nice earthy tones which give it that worn and old feeling.</td>', 'Nice earthy tones which give it that worn and old feeling.', '2008-03-29 11:23:07.000000', NULL, 1),
(4595330, 661809, 89547, '<td valign="top">Good photo,with good shadows and fading of the colros from dark to light. Great line too which help to move the eye.</td>', 'Good photo,with good shadows and fading of the colros from dark to light. Great line too which help to move the eye.', '2008-03-29 11:24:00.000000', NULL, 1),
(4595332, 660461, 89547, '<td valign="top">Nice angle and compostion invloved that make you think.</td>', 'Nice angle and compostion invloved that make you think.', '2008-03-29 11:24:20.000000', NULL, 1),
(4595333, 660125, 89547, '<td valign="top">Nice depth and reflection in the water by the light. the relfection leads you down the photo.</td>', 'Nice depth and reflection in the water by the light. the relfection leads you down the photo.', '2008-03-29 11:24:49.000000', NULL, 1),
(4595334, 662086, 89547, '<td valign="top">Good compostion and idea putting the nut where it is placed. Nice detail of the peanut shells too.</td>', 'Good compostion and idea putting the nut where it is placed. Nice detail of the peanut shells too.', '2008-03-29 11:25:21.000000', NULL, 1),
