(4595338, 660420, 89547, '<td valign="top">Nice alternating pattern of the colors creates an illusion to the eye.</td>', 'Nice alternating pattern of the colors creates an illusion to the eye.', '2008-03-29 11:26:27.000000', NULL, 1),
(4595339, 662072, 89547, '<td valign="top">Nice color and lines created which add great movement. the white backgrounf was a good idea.</td>', 'Nice color and lines created which add great movement. the white backgrounf was a good idea.', '2008-03-29 11:27:07.000000', NULL, 1),
(4595340, 662237, 89547, '<td valign="top">Nice shadows which make the object appear 3-D.</td>', 'Nice shadows which make the object appear 3-D.', '2008-03-29 11:27:41.000000', NULL, 1),
(4595341, 660129, 89547, '<td valign="top">Amazing! One of the best i have seen. Great form and shapes involved. The shadows created give in an optical illusion feel Great(10).</td>', 'Amazing! One of the best i have seen. Great form and shapes involved. The shadows created give in an optical illusion feel Great(10).', '2008-03-29 11:28:35.000000', NULL, 1),
