INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4595865, 661311, 83313, '<td valign="top">I feel lost in the desert. Need... water...</td>', 'I feel lost in the desert. Need... water...', '2008-03-29 18:21:05.000000', NULL, 1),
(4595866, 662260, 83313, '<td valign="top">I think you''ve got some decent composition going here, but the harsh flash makes it look like a casual snapshot.</td>', 'I think you''ve got some decent composition going here, but the harsh flash makes it look like a casual snapshot.', '2008-03-29 18:22:41.000000', NULL, 1),
(4595871, 661542, 55775, '<td valign="top">bit like a real life rubiks cube!! cool</td>', 'bit like a real life rubiks cube!! cool', '2008-03-29 18:27:03.000000', NULL, 1),
(4595874, 661927, 83313, '<td valign="top">Nice rich colors and details showing. <strike>Could have used a little perspective correction in PP.</strike> I just compared it against the edges of the browser window and all sides are straight, so it must be an optical illusion.</td>', 'Nice rich colors and details showing. Could have used a little perspective correction in PP. I just compared it against the edges of the browser window and all sides are straight, so it must be an optical illusion.', '2008-03-29 18:28:29.000000', NULL, 1),
(4595876, 660627, 83313, '<td valign="top">I really like the perspective view and the strong bold colors here, but I think the centered landscape crop may have been the wrong choice. A portrait orientation, with the building taking up more of the frame, may have had better visual flow.</td>', 'I really like the perspective view and the strong bold colors here, but I think the centered landscape crop may have been the wrong choice. A portrait orientation, with the building taking up more of the frame, may have had better visual flow.', '2008-03-29 18:30:58.000000', NULL, 1),
(4595879, 662160, 83313, '<td valign="top">Spelling police here. It''s "Curls". Sorry, it was bugging me and I had to mention it. <br/> <br/>It''s a random pattern, but still a pattern nonetheless. I remember reading an article a few years ago about the unpredictability of such things. Scientists were examining random distribution patterns of things like smoke and colors dropped in water. They were trying to find a way of predicting what is usually perceived as randomness.</td>', 'Spelling police here. It''s "Curls". Sorry, it was bugging me and I had to mention it.  It''s a random pattern, but still a pattern nonetheless. I remember reading an article a few years ago about the unpredictability of such things. Scientists were examining random distribution patterns of things like smoke and colors dropped in water. They were trying to find a way of predicting what is usually perceived as randomness.', '2008-03-29 18:35:57.000000', NULL, 1),
(4595881, 661911, 83313, '<td valign="top">Neat looking. Is it a sculpture, or a functional structure? Seems cropped a touch to close at the top for me.</td>', 'Neat looking. Is it a sculpture, or a functional structure? Seems cropped a touch to close at the top for me.', '2008-03-29 18:37:50.000000', NULL, 1),
(4595883, 661856, 83313, '<td valign="top">How appropriate. I just left a long winded comment on another smoke pattern entry about scientists investigating how randomness occurs. This one''s good too.</td>', 'How appropriate. I just left a long winded comment on another smoke pattern entry about scientists investigating how randomness occurs. This one''s good too.', '2008-03-29 18:39:31.000000', NULL, 1),
(4595884, 660304, 83313, '<td valign="top">Nice color tones. A little more DOF might have improved it some, though.</td>', 'Nice color tones. A little more DOF might have improved it some, though.', '2008-03-29 18:40:29.000000', NULL, 1),
(4595885, 662202, 83313, '<td valign="top">This leads my eye quite nicely to the water. I do find the top end of the frame to be a little crowded compared to the rest of the image.</td>', 'This leads my eye quite nicely to the water. I do find the top end of the frame to be a little crowded compared to the rest of the image.', '2008-03-29 18:42:20.000000', NULL, 1),
(4595890, 662042, 83313, '<td valign="top">Had to look at this a few moments to figure out what the perspective was. I might have done a little perspective correction on the left side, just to square it up. I think that would bump up the impact a notch.</td>', 'Had to look at this a few moments to figure out what the perspective was. I might have done a little perspective correction on the left side, just to square it up. I think that would bump up the impact a notch.', '2008-03-29 18:46:09.000000', NULL, 1),
(4595893, 662159, 83313, '<td valign="top">What great detail and a unique still life look at something.</td>', 'What great detail and a unique still life look at something.', '2008-03-29 18:47:41.000000', NULL, 1),
(4595895, 661962, 83313, '<td valign="top">This reminds me, the "Speed Racer" movie is opening soon. My second childhood has started. Vroom!!</td>', 'This reminds me, the "Speed Racer" movie is opening soon. My second childhood has started. Vroom!!', '2008-03-29 18:49:44.000000', NULL, 1),
(4595896, 662243, 83313, '<td valign="top">What is a "Frez"? Kinda neat looking whatever it is.</td>', 'What is a "Frez"? Kinda neat looking whatever it is.', '2008-03-29 18:50:38.000000', NULL, 1),
(4595899, 661649, 83313, '<td valign="top">Lost a little highlight detail over in the corner, but it''s not like that has not been the case on much of my own stuff. This is neat looking. At first glance, I almost thought it was an odd kind of cheese.</td>', 'Lost a little highlight detail over in the corner, but it''s not like that has not been the case on much of my own stuff. This is neat looking. At first glance, I almost thought it was an odd kind of cheese.', '2008-03-29 18:52:32.000000', NULL, 1),
