(4595902, 660593, 83313, '<td valign="top">Either the lighting is very harsh, or you oversharpened this a bit. A close up view of this coral would have been good.</td>', 'Either the lighting is very harsh, or you oversharpened this a bit. A close up view of this coral would have been good.', '2008-03-29 18:56:38.000000', NULL, 1),
(4595917, 661893, 79955, '<td valign="top">Pic not too level. In general good job in getting the details. "WOW" factor is lacking &amp; will likely be the man reason that will prevent the image from scoring higher. 6</td>', 'Pic not too level. In general good job in getting the details. "WOW" factor is lacking & will likely be the man reason that will prevent the image from scoring higher. 6', '2008-03-29 19:18:14.000000', NULL, 1),
(4595921, 661647, 79955, '<td valign="top">Nice image teammate. My main gripe with the image is that the lower right portion of dense shadow area from the trees spoil the pattern &amp; the repetitiveness. Technically nothing wrong.<br/>FYI : comment only &amp; did not rate.</td>', 'Nice image teammate. My main gripe with the image is that the lower right portion of dense shadow area from the trees spoil the pattern & the repetitiveness. Technically nothing wrong.FYI : comment only & did not rate.', '2008-03-29 19:21:28.000000', NULL, 1),
(4595928, 660682, 79955, '<td valign="top">Meets the challenge , only problem is that subject (especially) &amp; lighting is not exciting enough to convince the voter to vote higher. 6</td>', 'Meets the challenge , only problem is that subject (especially) & lighting is not exciting enough to convince the voter to vote higher. 6', '2008-03-29 19:23:45.000000', NULL, 1),
(4595931, 661575, 79955, '<td valign="top">I would have preferred much more sky with the scaley cloud patterns. Overall nice shot but still lacking that bit of "WOW" factor. 6</td>', 'I would have preferred much more sky with the scaley cloud patterns. Overall nice shot but still lacking that bit of "WOW" factor. 6', '2008-03-29 19:25:43.000000', NULL, 1),
