(4596178, 660363, 17203, '<td valign="top">I''m not sure what color ribbon this is. Looks like taupe, but I''m leaning toward blue. I do know it''s a 10 and my top pick. Awesome!</td>', 'I''m not sure what color ribbon this is. Looks like taupe, but I''m leaning toward blue. I do know it''s a 10 and my top pick. Awesome!', '2008-03-29 22:41:06.000000', NULL, 1),
(4596179, 660634, 17203, '<td valign="top">Wonderful tones, strong composition and delicate detail. You couldn''t have timed this any better, and B&amp;W was a great choice to focus attention on the forms. One of my top three picks and easily worthy of a 10.</td>', 'Wonderful tones, strong composition and delicate detail. You couldn''t have timed this any better, and B&W was a great choice to focus attention on the forms. One of my top three picks and easily worthy of a 10.', '2008-03-29 22:43:42.000000', NULL, 1),
(4596180, 660319, 48697, '<td valign="top">I like the play of light in this shot, has a ying/yang quality to it. Dark to light to dark to light, nicely seen and nicely done.</td>', 'I like the play of light in this shot, has a ying/yang quality to it. Dark to light to dark to light, nicely seen and nicely done.', '2008-03-29 22:45:36.000000', NULL, 1),
