(4596205, 661113, 48697, '<td valign="top">Pattern in chaos, nice pic and take on the challenge.</td>', 'Pattern in chaos, nice pic and take on the challenge.', '2008-03-29 23:05:55.000000', NULL, 1),
(4596210, 660129, 17203, '<td valign="top">There were so many architecture photos in the challenge, but this one really stands out with a great sense of depth and scale. The highlights are a little too hot for my taste, but not enough to bring down a well deserved 10. ;-)</td>', 'There were so many architecture photos in the challenge, but this one really stands out with a great sense of depth and scale. The highlights are a little too hot for my taste, but not enough to bring down a well deserved 10. ;-)', '2008-03-29 23:08:42.000000', NULL, 1),
(4596215, 661713, 17203, '<td valign="top">This is not the sort of image I normally rate high from a technical standpoint... with harsh lighting and a grainy feel, but it''s a refreshing take on the challenge and an inviting Old-World scene. A good black and white conversion would have solved the technical issues IMO, but this is still one of my top 5 picks. Great shot! 9</td>', 'This is not the sort of image I normally rate high from a technical standpoint... with harsh lighting and a grainy feel, but it''s a refreshing take on the challenge and an inviting Old-World scene. A good black and white conversion would have solved the technical issues IMO, but this is still one of my top 5 picks. Great shot! 9', '2008-03-29 23:13:31.000000', NULL, 1),
(4596225, 662137, 17203, '<td valign="top">This entry lacks the strong repetition of my other top picks for Pattern, but the sheer artistry of the composition is awesome. I could easily see a large print selling for thousands just for its beauty, and this would be equally appropriate for a Free Study. Nice! 9</td>', 'This entry lacks the strong repetition of my other top picks for Pattern, but the sheer artistry of the composition is awesome. I could easily see a large print selling for thousands just for its beauty, and this would be equally appropriate for a Free Study. Nice! 9', '2008-03-29 23:19:29.000000', NULL, 1),
