(4597036, 662183, 59029, '<td valign="top">OK I''m jealous, how''d you do this?! lively, colourful, fun. dare I say Top 10? 10</td>', 'OK I''m jealous, how''d you do this?! lively, colourful, fun. dare I say Top 10? 10', '2008-03-30 16:54:07.000000', NULL, 1),
(4597037, 661961, 59029, '<td valign="top">proof that a good pic doesn''t have to be full of saturated colours to work well.  achingly simple. 8</td>', 'proof that a good pic doesn''t have to be full of saturated colours to work well.  achingly simple. 8', '2008-03-30 16:54:43.000000', NULL, 1),
(4597038, 662262, 59029, '<td valign="top">cool shot of damp peppercorns!  But the pink ones are actually a little sweet :-) 8</td>', 'cool shot of damp peppercorns!  But the pink ones are actually a little sweet :-) 8', '2008-03-30 16:55:35.000000', NULL, 1),
(4597043, 660634, 86447, '<td valign="top">Wow!  What a pattern!  One of few 10s I''ve given.  The shadows and the building''s edge just make this almost perfect.   Well done...  (applause)</td>', 'Wow!  What a pattern!  One of few 10s I''ve given.  The shadows and the building''s edge just make this almost perfect.   Well done...  (applause)', '2008-03-30 16:59:46.000000', NULL, 1),
(4597045, 662119, 86447, '<td valign="top">Incredible.  If it hadn''t been validated, I''d think it wasn''t possible.  *grin*   A well done 10.  One of few.</td>', 'Incredible.  If it hadn''t been validated, I''d think it wasn''t possible.  *grin*   A well done 10.  One of few.', '2008-03-30 17:01:09.000000', NULL, 1),
(4597047, 662137, 86447, '<td valign="top">A simple ten.<br/> <br/>The curves and colors just really please.</td>', 'A simple ten. The curves and colors just really please.', '2008-03-30 17:01:35.000000', NULL, 1),
(4597050, 662177, 86447, '<td valign="top">The focus is great and having the hand for scale is wonderful.   Well done.</td>', 'The focus is great and having the hand for scale is wonderful.   Well done.', '2008-03-30 17:02:08.000000', NULL, 1),
(4597052, 661602, 86447, '<td valign="top">Wow... I really like these shadows and colors.   Simple and beautiful.</td>', 'Wow... I really like these shadows and colors.   Simple and beautiful.', '2008-03-30 17:02:29.000000', NULL, 1),
(4597053, 660627, 86447, '<td valign="top">Fabulous!   The colors and the angle... really fun.</td>', 'Fabulous!   The colors and the angle... really fun.', '2008-03-30 17:02:49.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4597054, 662160, 86447, '<td valign="top">Smoke is a bit overdone here, I think... but this is a well-done over-done shot.   *grin*</td>', 'Smoke is a bit overdone here, I think... but this is a well-done over-done shot.   *grin*', '2008-03-30 17:03:15.000000', NULL, 1),
(4597055, 661756, 86447, '<td valign="top">Very cool.</td>', 'Very cool.', '2008-03-30 17:03:28.000000', NULL, 1),
(4597056, 662042, 86447, '<td valign="top">One of my faves... really fun patterns that demand examination.  Could have upped the saturation and curves a bit, I think.</td>', 'One of my faves... really fun patterns that demand examination.  Could have upped the saturation and curves a bit, I think.', '2008-03-30 17:04:00.000000', NULL, 1),
(4597082, 660349, 90658, '<td valign="top">For me, this one is sort of the opposite of patterns.  It is the break in the patterns that attract my attention...the damage vs. the non-damage.</td>', 'For me, this one is sort of the opposite of patterns.  It is the break in the patterns that attract my attention...the damage vs. the non-damage.', '2008-03-30 17:22:42.000000', NULL, 1),
(4597085, 661925, 90658, '<td valign="top">With a little research, I found your pattern.</td>', 'With a little research, I found your pattern.', '2008-03-30 17:25:33.000000', NULL, 1),
(4597088, 662274, 90658, '<td valign="top">This is just me, but I would have liked to see the entire circle (chrome one), not just a portion.  The concentric circles are a pattern as well as the "blades."</td>', 'This is just me, but I would have liked to see the entire circle (chrome one), not just a portion.  The concentric circles are a pattern as well as the "blades."', '2008-03-30 17:26:51.000000', NULL, 1),
(4597091, 660404, 90658, '<td valign="top">Interesting view of the power line tower.  I wonder how it feel to be on a train zooming underneath these.</td>', 'Interesting view of the power line tower.  I wonder how it feel to be on a train zooming underneath these.', '2008-03-30 17:27:50.000000', NULL, 1),
(4597094, 659799, 90658, '<td valign="top">I''m hoping that the pattern being communicated is the speckling of the nut bud.  As that is the only one I see, and it is extremely subtle.  I''m not really sure why this shot leaves me flat, but such is art.</td>', 'I''m hoping that the pattern being communicated is the speckling of the nut bud.  As that is the only one I see, and it is extremely subtle.  I''m not really sure why this shot leaves me flat, but such is art.', '2008-03-30 17:29:29.000000', NULL, 1),
(4597100, 662243, 90658, '<td valign="top">This is an interesting idea.  I''m not sure that the straight on angle is the best, but at least the bulb is not smack dab centered.</td>', 'This is an interesting idea.  I''m not sure that the straight on angle is the best, but at least the bulb is not smack dab centered.', '2008-03-30 17:30:44.000000', NULL, 1),
(4597111, 661422, 90658, '<td valign="top">So, are you wanting us to look past the obvious vertically linear pattern into the abstract ones in the reflection?  I''m guessing so as the title sort of indicates that.  My problem is the general lack of depth.  Everything is demanding my attention at once and it is almost too much visually.</td>', 'So, are you wanting us to look past the obvious vertically linear pattern into the abstract ones in the reflection?  I''m guessing so as the title sort of indicates that.  My problem is the general lack of depth.  Everything is demanding my attention at once and it is almost too much visually.', '2008-03-30 17:37:36.000000', NULL, 1),
(4597117, 662177, 90658, '<td valign="top">The pink of the skin offsets the green of the turtle nicely.  It is easy to see the patterns on the animal.  My question is sort of nit-picky, were there other ways to show this animal?  The fingers all splayed out are sort of a secondary subject and they don''t really fit (other than to show the size of the animal).  It sort of minimizes the effect of the natural patterns on the turtle.</td>', 'The pink of the skin offsets the green of the turtle nicely.  It is easy to see the patterns on the animal.  My question is sort of nit-picky, were there other ways to show this animal?  The fingers all splayed out are sort of a secondary subject and they don''t really fit (other than to show the size of the animal).  It sort of minimizes the effect of the natural patterns on the turtle.', '2008-03-30 17:41:10.000000', NULL, 1),
(4597118, 660187, 90658, '<td valign="top">Sort of abstract interpretation of the challenge, but well executed.</td>', 'Sort of abstract interpretation of the challenge, but well executed.', '2008-03-30 17:41:53.000000', NULL, 1),
(4597119, 661636, 90658, '<td valign="top">Art speaks differently to different people.</td>', 'Art speaks differently to different people.', '2008-03-30 17:42:27.000000', NULL, 1),
(4597121, 662124, 90658, '<td valign="top">There are places where your backlighting is blowing out the vein structure.</td>', 'There are places where your backlighting is blowing out the vein structure.', '2008-03-30 17:43:01.000000', NULL, 1),
(4597122, 662062, 90658, '<td valign="top">Colors are really muted.</td>', 'Colors are really muted.', '2008-03-30 17:43:23.000000', NULL, 1),
(4597123, 661192, 90658, '<td valign="top">I''m having a really hard time defining what is going on in the background.  And there is a "reflection" or some sort of something underneath the ice that seems out of place.  If I could see the background better, things might come together into a better whole.</td>', 'I''m having a really hard time defining what is going on in the background.  And there is a "reflection" or some sort of something underneath the ice that seems out of place.  If I could see the background better, things might come together into a better whole.', '2008-03-30 17:45:03.000000', NULL, 1),
(4597124, 662254, 90658, '<td valign="top">I don''t think you needed the candy or doll or whatever is in the center of the rings.  The dimension and concentricity is well communicated without it.</td>', 'I don''t think you needed the candy or doll or whatever is in the center of the rings.  The dimension and concentricity is well communicated without it.', '2008-03-30 17:46:00.000000', NULL, 1),
(4597125, 661815, 90658, '<td valign="top">Almost too subtle for this challenge.</td>', 'Almost too subtle for this challenge.', '2008-03-30 17:46:21.000000', NULL, 1),
(4597129, 661873, 90658, '<td valign="top">I have always been a fan of the editorial comment of architecture.  To have three distinct design theories next together and "cohabitating" as opposed to "competeing" is quite pleasing to the eye.</td>', 'I have always been a fan of the editorial comment of architecture.  To have three distinct design theories next together and "cohabitating" as opposed to "competeing" is quite pleasing to the eye.', '2008-03-30 17:47:48.000000', NULL, 1),
(4597136, 660880, 89758, '<td valign="top">Wow! Great lighting. The way the balconies pop out is awesome. Makes it seem like it''s 3D.</td>', 'Wow! Great lighting. The way the balconies pop out is awesome. Makes it seem like it''s 3D.', '2008-03-30 17:51:15.000000', NULL, 1),
(4597137, 662223, 90658, '<td valign="top">My issue here is focal point.  The creative opportunities in this shot are staggering.  So much could have been done simply by playing with focal point.  You title this shot "bump" but then focus is on the center of a ridge in the center of the shot.  You could have picked any bolt, any imperfection or even the joint in the bird''s leg and created a more impactful shot.  The compostion and angle is perfect, don''t change those.  Just experiment more with focal point.</td>', 'My issue here is focal point.  The creative opportunities in this shot are staggering.  So much could have been done simply by playing with focal point.  You title this shot "bump" but then focus is on the center of a ridge in the center of the shot.  You could have picked any bolt, any imperfection or even the joint in the bird''s leg and created a more impactful shot.  The compostion and angle is perfect, don''t change those.  Just experiment more with focal point.', '2008-03-30 17:51:29.000000', NULL, 1),
(4597139, 660634, 89758, '<td valign="top">This reminds me of a flower for some reason. It''s light, delicate, and sort of blossoms. Anyway, it''s a great pic. Something I''d hang in my room.</td>', 'This reminds me of a flower for some reason. It''s light, delicate, and sort of blossoms. Anyway, it''s a great pic. Something I''d hang in my room.', '2008-03-30 17:52:57.000000', NULL, 1),
(4597140, 661850, 90658, '<td valign="top">This is one of those shots that could stand alone as is and be generally ok.  The creativity that presented itself was sort of left alone.  This is an abacus and those little balls could be moved around to create some secondary pattern dimension.  A wider angle, some creative movement of beads (don''t worry if the pattern is not correct for an abacus, you aren''t calculating anything) and you would have something extra special.</td>', 'This is one of those shots that could stand alone as is and be generally ok.  The creativity that presented itself was sort of left alone.  This is an abacus and those little balls could be moved around to create some secondary pattern dimension.  A wider angle, some creative movement of beads (don''t worry if the pattern is not correct for an abacus, you aren''t calculating anything) and you would have something extra special.', '2008-03-30 17:54:21.000000', NULL, 1),
(4597142, 662278, 90658, '<td valign="top">This seems too dark for my tastes, but that is subjective.</td>', 'This seems too dark for my tastes, but that is subjective.', '2008-03-30 17:54:50.000000', NULL, 1),
(4597144, 662000, 90658, '<td valign="top">This is pretty, but for some reason it misses my "Wow" button.  Send this to the critique club or the forums and I bet you could get some great ideas.</td>', 'This is pretty, but for some reason it misses my "Wow" button.  Send this to the critique club or the forums and I bet you could get some great ideas.', '2008-03-30 17:55:44.000000', NULL, 1),
(4597145, 662160, 90892, '<td valign="top">I am tired of smoke shots but you did a good job. The lines are very crisp.</td>', 'I am tired of smoke shots but you did a good job. The lines are very crisp.', '2008-03-30 17:56:35.000000', NULL, 1),
(4597147, 662222, 90658, '<td valign="top">I love this whistling reeds.  They are fun to play with and haunting to hear in the wind.  That being said, I think you have stretched the pattern idea a really long way to get this in.  There is a slight color pattern on the stalks but you have effectively removed it with your dof choice.  It is a nice well-thought shot and would probably do really well in a different challenge.</td>', 'I love this whistling reeds.  They are fun to play with and haunting to hear in the wind.  That being said, I think you have stretched the pattern idea a really long way to get this in.  There is a slight color pattern on the stalks but you have effectively removed it with your dof choice.  It is a nice well-thought shot and would probably do really well in a different challenge.', '2008-03-30 17:58:01.000000', NULL, 1),
(4597149, 660419, 89758, '<td valign="top">interesting angle and composition. I like it</td>', 'interesting angle and composition. I like it', '2008-03-30 17:59:36.000000', NULL, 1),
(4597150, 662232, 90658, '<td valign="top">I think my biggest problem is figuring out what the main subject is.  The brick work in the roadway is the most obvious pattern, but the road is not even the third thing I see.  If the title wasn''t there, I would not really know what I was looking at.</td>', 'I think my biggest problem is figuring out what the main subject is.  The brick work in the roadway is the most obvious pattern, but the road is not even the third thing I see.  If the title wasn''t there, I would not really know what I was looking at.', '2008-03-30 17:59:40.000000', NULL, 1),
(4597151, 662250, 90658, '<td valign="top">Very abstract pattern.  The black bars at the top and bottom seem to add geometric finality to the shot.  Since it is so abstract, I would love to see this without the edges or border or whatever that is.  Let my imagination fill in the infinite with this one.</td>', 'Very abstract pattern.  The black bars at the top and bottom seem to add geometric finality to the shot.  Since it is so abstract, I would love to see this without the edges or border or whatever that is.  Let my imagination fill in the infinite with this one.', '2008-03-30 18:01:44.000000', NULL, 1),
(4597153, 661898, 90892, '<td valign="top">This made me look for quite a while so it must be good. I''m still looking. I''m still looking.  Can''t put my finger on why but I like it.</td>', 'This made me look for quite a while so it must be good. I''m still looking. I''m still looking.  Can''t put my finger on why but I like it.', '2008-03-30 18:02:40.000000', NULL, 1),
(4597155, 662119, 90892, '<td valign="top">How did you do this? Love it.</td>', 'How did you do this? Love it.', '2008-03-30 18:03:54.000000', NULL, 1),
(4597156, 661990, 90658, '<td valign="top">These trees are so cool.  I love them.  This is a nice natural shot, which is probably going to get you in trouble.  You have dared to let something stand on it''s own even with it''s natural imperfections.  Even if this weren''t basic, I would suggest leaving this as is, if anything a teeny bit of play with contrast, but don''t let people talk you into removing the imperfections in the leaves.</td>', 'These trees are so cool.  I love them.  This is a nice natural shot, which is probably going to get you in trouble.  You have dared to let something stand on it''s own even with it''s natural imperfections.  Even if this weren''t basic, I would suggest leaving this as is, if anything a teeny bit of play with contrast, but don''t let people talk you into removing the imperfections in the leaves.', '2008-03-30 18:03:59.000000', NULL, 1),
(4597158, 661963, 90658, '<td valign="top">Subtlty in pattern.  The backlighting is a different presentation of a common theme.  There is just something that falls short for me.  Art speaks differently to different people.</td>', 'Subtlty in pattern.  The backlighting is a different presentation of a common theme.  There is just something that falls short for me.  Art speaks differently to different people.', '2008-03-30 18:05:29.000000', NULL, 1),
(4597160, 662264, 90658, '<td valign="top">My quibble is with choice of focal point.  It seems to be behind the eye, and slightly below the blue scales.  I would suggest bringing more of the face into the focus, that''s where most of the interesting patterns exist.</td>', 'My quibble is with choice of focal point.  It seems to be behind the eye, and slightly below the blue scales.  I would suggest bringing more of the face into the focus, that''s where most of the interesting patterns exist.', '2008-03-30 18:07:09.000000', NULL, 1),
(4597164, 660818, 90892, '<td valign="top">Maybe this would have been better in color. Maybe not. Just seems kind of dark and flat. Good idea and good title though.</td>', 'Maybe this would have been better in color. Maybe not. Just seems kind of dark and flat. Good idea and good title though.', '2008-03-30 18:10:35.000000', NULL, 1),
(4597165, 661683, 90658, '<td valign="top">This one could have been stunning with a bit of time and prep work.  Imagine that every lollipop were turned so the name of the candy was lined up.  Imagine, if the flavors/colors of the wrappers were organized into a pattern.  Then you would have the following:<br/>1) Horizontal pattern<br/>2) Vertical pattern<br/>3) Name linear sameness (just another pattern)<br/>4) Color cohesion<br/> <br/>Four patterns all in one shot!  Of course, then people might say it was too boring and you should randomnize things.  Can''t win, can you?!</td>', 'This one could have been stunning with a bit of time and prep work.  Imagine that every lollipop were turned so the name of the candy was lined up.  Imagine, if the flavors/colors of the wrappers were organized into a pattern.  Then you would have the following:1) Horizontal pattern2) Vertical pattern3) Name linear sameness (just another pattern)4) Color cohesion Four patterns all in one shot!  Of course, then people might say it was too boring and you should randomnize things.  Can''t win, can you?!', '2008-03-30 18:10:44.000000', NULL, 1),
(4597167, 662206, 90658, '<td valign="top">This is rather interesting.  The lighting is so subdued, then you have this harsh bulb right at the bottom...which is the first thing I see.  Perhaps use a red bulb next time, it would give the illusion of self illumination.</td>', 'This is rather interesting.  The lighting is so subdued, then you have this harsh bulb right at the bottom...which is the first thing I see.  Perhaps use a red bulb next time, it would give the illusion of self illumination.', '2008-03-30 18:12:09.000000', NULL, 1),
