INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4598755, 661945, 89426, '<td valign="top">Even though this object is so simple, ilike the two different colors that you included. They create a nice gradient of movement.</td>', 'Even though this object is so simple, ilike the two different colors that you included. They create a nice gradient of movement.', '2008-03-31 11:18:13.000000', NULL, 1),
(4598756, 661987, 89426, '<td valign="top">I like the angle that you captured this shot from. It adds a lot of diversity to the image.</td>', 'I like the angle that you captured this shot from. It adds a lot of diversity to the image.', '2008-03-31 11:19:02.000000', NULL, 1),
(4598757, 662074, 89426, '<td valign="top">I like how simple this image is, but it is beautiful. The colors work very well together.</td>', 'I like how simple this image is, but it is beautiful. The colors work very well together.', '2008-03-31 11:19:38.000000', NULL, 1),
(4598758, 662214, 91314, '<td valign="top">When I first looked at the photo at the beginning of the week I was thinking that it was too bright which took out some of the pattern. But the more I look at it the more I see that the sun gives a second kind of pattern which is intreguiging and would have not noticed that at first glance myself.  Now that I see it clearly I can now vote it higher than what I previously voted.  Well done and fantastic vision for this challange.</td>', 'When I first looked at the photo at the beginning of the week I was thinking that it was too bright which took out some of the pattern. But the more I look at it the more I see that the sun gives a second kind of pattern which is intreguiging and would have not noticed that at first glance myself.  Now that I see it clearly I can now vote it higher than what I previously voted.  Well done and fantastic vision for this challange.', '2008-03-31 11:19:55.000000', NULL, 1),
(4598763, 661636, 89426, '<td valign="top">The way you took this image makes it look like it could be anything. Nice choice in an angle</td>', 'The way you took this image makes it look like it could be anything. Nice choice in an angle', '2008-03-31 11:20:23.000000', NULL, 1),
