(4600198, 661660, 89422, '<td valign="top">I like the contrast in this picture!<br/>The focus is clear and the saturation is nice.<br/>Good job!</td>', 'I like the contrast in this picture!The focus is clear and the saturation is nice.Good job!', '2008-03-31 23:58:52.000000', NULL, 1),
(4600201, 662118, 89422, '<td valign="top">Very clever. Great idea, and focused crystal clear.</td>', 'Very clever. Great idea, and focused crystal clear.', '2008-03-31 23:59:51.000000', NULL, 1),
(4600204, 661849, 89422, '<td valign="top">Try zooming in a little closer.</td>', 'Try zooming in a little closer.', '2008-04-01 00:00:06.000000', NULL, 1),
(4600205, 661961, 89422, '<td valign="top">If I could see more of the stairs, it might look better.</td>', 'If I could see more of the stairs, it might look better.', '2008-04-01 00:00:32.000000', NULL, 1),
(4600207, 662278, 89422, '<td valign="top">Very nicely done. Great focus, vivid colors, and great lighting.<br/>Maybe if it wasn''t in dead center?</td>', 'Very nicely done. Great focus, vivid colors, and great lighting.Maybe if it wasn''t in dead center?', '2008-04-01 00:01:11.000000', NULL, 1),
(4600209, 661830, 89422, '<td valign="top">A nicely taken picture with impressive contrast. But, its size is a small issue.</td>', 'A nicely taken picture with impressive contrast. But, its size is a small issue.', '2008-04-01 00:01:52.000000', NULL, 1),
(4600211, 662234, 89422, '<td valign="top">Good color and focus, but the picture is not very eye catching.</td>', 'Good color and focus, but the picture is not very eye catching.', '2008-04-01 00:02:54.000000', NULL, 1),
(4600214, 662075, 89422, '<td valign="top">The shot is beautiful, but the pattern isn''t very evident.</td>', 'The shot is beautiful, but the pattern isn''t very evident.', '2008-04-01 00:03:26.000000', NULL, 1),
(4600215, 661850, 89422, '<td valign="top">And abacus! Great Idea. Vivid colors and a great angle!</td>', 'And abacus! Great Idea. Vivid colors and a great angle!', '2008-04-01 00:03:59.000000', NULL, 1),
(4600216, 662227, 89422, '<td valign="top">Good idea, but it might look better from a different angle.</td>', 'Good idea, but it might look better from a different angle.', '2008-04-01 00:04:28.000000', NULL, 1),
(4600218, 661223, 89723, '<td valign="top">The more I look at this shot, the more I like it. A simple, yet very effective interpretation of the challenge. White, Silver, and Light are not easy to work with by themselves, never mind all together. Well above my average! Nice Job.</td>', 'The more I look at this shot, the more I like it. A simple, yet very effective interpretation of the challenge. White, Silver, and Light are not easy to work with by themselves, never mind all together. Well above my average! Nice Job.', '2008-04-01 00:04:38.000000', NULL, 1);
