(4600219, 660678, 89422, '<td valign="top">A very interesting concept. Maybe you could have gotten shells with a little more color?</td>', 'A very interesting concept. Maybe you could have gotten shells with a little more color?', '2008-04-01 00:04:56.000000', NULL, 1),
(4600221, 662207, 89422, '<td valign="top">The inverted colors really bring out the patterns, and the colors help make the picture interesting.</td>', 'The inverted colors really bring out the patterns, and the colors help make the picture interesting.', '2008-04-01 00:05:45.000000', NULL, 1),
(4600223, 660404, 89422, '<td valign="top">A very good angle with a beautiful back ground. Nice job.</td>', 'A very good angle with a beautiful back ground. Nice job.', '2008-04-01 00:06:14.000000', NULL, 1),
(4600224, 660604, 89422, '<td valign="top">Although the focus is nice, the contrast could use some work.</td>', 'Although the focus is nice, the contrast could use some work.', '2008-04-01 00:07:05.000000', NULL, 1),
(4600225, 661920, 89422, '<td valign="top">The drastic difference between the shades of blue really make the picture stand out <br/>Well done.</td>', 'The drastic difference between the shades of blue really make the picture stand out Well done.', '2008-04-01 00:07:34.000000', NULL, 1),
