(4603843, 662136, 89429, '<td valign="top">awesome photo.  nice concept.</td>', 'awesome photo.  nice concept.', '2008-04-01 21:38:45.000000', NULL, 1),
(4603963, 661427, 67697, '<td valign="top">This is how I wish my black and white photos would turn out.  It''s beautiful!</td>', 'This is how I wish my black and white photos would turn out.  It''s beautiful!', '2008-04-01 22:31:12.000000', NULL, 1),
(4603980, 660553, 80979, '<td valign="top">would have been nicer in color...</td>', 'would have been nicer in color...', '2008-04-01 22:36:35.000000', NULL, 1),
(4604040, 661533, 90658, '<td valign="top">The vertical lines really elongate this giving the illusion of infinity.</td>', 'The vertical lines really elongate this giving the illusion of infinity.', '2008-04-01 22:54:18.000000', NULL, 1),
(4604042, 661011, 90658, '<td valign="top">Nicely captured.</td>', 'Nicely captured.', '2008-04-01 22:54:35.000000', NULL, 1),
(4604046, 662050, 90658, '<td valign="top">Sort of flat, imo.  Nice attempt though.</td>', 'Sort of flat, imo.  Nice attempt though.', '2008-04-01 22:54:58.000000', NULL, 1),
(4604047, 660460, 90658, '<td valign="top">Nice capture of what I am guessing is a prized keepsake.</td>', 'Nice capture of what I am guessing is a prized keepsake.', '2008-04-01 22:55:30.000000', NULL, 1),
(4604049, 661745, 90658, '<td valign="top">This is so much more stunning in the large format vs. the thumbnail.</td>', 'This is so much more stunning in the large format vs. the thumbnail.', '2008-04-01 22:56:05.000000', NULL, 1),
(4604051, 662133, 90658, '<td valign="top">Very intriguing mosaic.  Were the colors originally this muted?  If not, I would love to see the original.</td>', 'Very intriguing mosaic.  Were the colors originally this muted?  If not, I would love to see the original.', '2008-04-01 22:56:51.000000', NULL, 1),
(4604052, 660328, 90658, '<td valign="top">Art speaks differently to different people.</td>', 'Art speaks differently to different people.', '2008-04-01 22:57:18.000000', NULL, 1),
(4604057, 660595, 90658, '<td valign="top">You know, I was wondering if anyone was going to do bubble wrap.  How long did you play with it after you got your shot?  Did you pop the entire sheet or just part of it?</td>', 'You know, I was wondering if anyone was going to do bubble wrap.  How long did you play with it after you got your shot?  Did you pop the entire sheet or just part of it?', '2008-04-01 22:58:12.000000', NULL, 1),
(4604062, 662150, 90658, '<td valign="top">Beautiful lace.  Was it handmade?  Wish I could see more of it, just to enjoy the beauty.</td>', 'Beautiful lace.  Was it handmade?  Wish I could see more of it, just to enjoy the beauty.', '2008-04-01 22:59:00.000000', NULL, 1),
(4604063, 661587, 90658, '<td valign="top">Try to use the maximum size alloted for your presentations.  It makes it easier to see them.</td>', 'Try to use the maximum size alloted for your presentations.  It makes it easier to see them.', '2008-04-01 22:59:34.000000', NULL, 1),
(4604067, 661067, 90658, '<td valign="top">Seems a little flat to me.  Perhaps play with the background a bit.  A very soft pale color would really punch the black/gray/white of the shell.</td>', 'Seems a little flat to me.  Perhaps play with the background a bit.  A very soft pale color would really punch the black/gray/white of the shell.', '2008-04-01 23:00:50.000000', NULL, 1),
(4604070, 662227, 90658, '<td valign="top">Very elegant fence line.</td>', 'Very elegant fence line.', '2008-04-01 23:01:13.000000', NULL, 1),
(4604078, 662207, 90658, '<td valign="top">I like the experiment with the reverse negative on this.</td>', 'I like the experiment with the reverse negative on this.', '2008-04-01 23:03:08.000000', NULL, 1),
(4604083, 661941, 90658, '<td valign="top">Art speaks differently to different people.</td>', 'Art speaks differently to different people.', '2008-04-01 23:04:13.000000', NULL, 1),
(4604085, 660000, 90658, '<td valign="top">A little too dark for my tastes, but you shouldn''t shoot to my tastes :)</td>', 'A little too dark for my tastes, but you shouldn''t shoot to my tastes :)', '2008-04-01 23:04:47.000000', NULL, 1),
(4604091, 660769, 90658, '<td valign="top">I''m wondering how many people figured out this was an old vinyl lp record.</td>', 'I''m wondering how many people figured out this was an old vinyl lp record.', '2008-04-01 23:05:41.000000', NULL, 1),
(4604096, 661682, 90658, '<td valign="top">Art speaks differently to different people.  I might get this better if I was standing in front of the original.</td>', 'Art speaks differently to different people.  I might get this better if I was standing in front of the original.', '2008-04-01 23:07:38.000000', NULL, 1),
(4604099, 660127, 90658, '<td valign="top">Please try to use the maximum alotted pixel area.  It makes it easier to see.</td>', 'Please try to use the maximum alotted pixel area.  It makes it easier to see.', '2008-04-01 23:08:22.000000', NULL, 1),
(4604103, 660809, 90658, '<td valign="top">I appreciate the angle that places the sun directly behind one of the girders.</td>', 'I appreciate the angle that places the sun directly behind one of the girders.', '2008-04-01 23:09:02.000000', NULL, 1),
(4604104, 661856, 90658, '<td valign="top">I''d prefer to see more of the curling effects at the top and less of the "straight" at the bottom.</td>', 'I''d prefer to see more of the curling effects at the top and less of the "straight" at the bottom.', '2008-04-01 23:09:41.000000', NULL, 1),
(4604109, 661607, 90658, '<td valign="top">Funny, too funny.  Was the cropping of the head on purpose?</td>', 'Funny, too funny.  Was the cropping of the head on purpose?', '2008-04-01 23:10:26.000000', NULL, 1),
(4604113, 662252, 90658, '<td valign="top">I''m having a hard time with the dimension.  I can see the angles of the building, but they don''t seem as defined as they could be.  Perhaps send to Critique Club or to one of the forums for some more technical advice.</td>', 'I''m having a hard time with the dimension.  I can see the angles of the building, but they don''t seem as defined as they could be.  Perhaps send to Critique Club or to one of the forums for some more technical advice.', '2008-04-01 23:12:01.000000', NULL, 1),
(4604115, 662263, 90658, '<td valign="top">Sometimes the simple ones say it all!</td>', 'Sometimes the simple ones say it all!', '2008-04-01 23:12:23.000000', NULL, 1),
(4604124, 662089, 90658, '<td valign="top">Definitely one of those shots where timing is everything.  In the Spring, Summer or Fall this would never be seen.</td>', 'Definitely one of those shots where timing is everything.  In the Spring, Summer or Fall this would never be seen.', '2008-04-01 23:15:02.000000', NULL, 1),
(4604129, 662108, 90658, '<td valign="top">Oddly enough, I wish there were more spores left on the dandelion puff.  That is just me, though and is not a criticism of the shot.</td>', 'Oddly enough, I wish there were more spores left on the dandelion puff.  That is just me, though and is not a criticism of the shot.', '2008-04-01 23:16:06.000000', NULL, 1),
(4604130, 660602, 90658, '<td valign="top">Simplicity at it''s best.</td>', 'Simplicity at it''s best.', '2008-04-01 23:16:26.000000', NULL, 1),
(4604132, 661597, 90658, '<td valign="top">Art speaks differently to different people.</td>', 'Art speaks differently to different people.', '2008-04-01 23:17:16.000000', NULL, 1),
(4604136, 662103, 90658, '<td valign="top">Simple design.  Unfortunately, this angle seems flat to me.</td>', 'Simple design.  Unfortunately, this angle seems flat to me.', '2008-04-01 23:18:41.000000', NULL, 1),
(4604141, 662250, 91776, '<td valign="top">simply magical</td>', 'simply magical', '2008-04-01 23:19:32.000000', NULL, 1),
(4604143, 662233, 90658, '<td valign="top">I think the dof is obscuring too much of the pattern.  Perhaps adjust it to start between the second and third pairing of forks.</td>', 'I think the dof is obscuring too much of the pattern.  Perhaps adjust it to start between the second and third pairing of forks.', '2008-04-01 23:19:53.000000', NULL, 1),
(4604147, 661724, 90658, '<td valign="top">The bowl of the spoon not only refracts the colors, it intensifies them.  Well done.</td>', 'The bowl of the spoon not only refracts the colors, it intensifies them.  Well done.', '2008-04-01 23:20:36.000000', NULL, 1),
(4604155, 660403, 90658, '<td valign="top">What makes this interesting is what makes it different.  A spiral fire escape is so out of the ordinary, that its presence already pops this shot.  Then seeing three alcoves that obviously used to be windows is another odd element.  The two together, makes for a visually stimulating shot.  Thank you.</td>', 'What makes this interesting is what makes it different.  A spiral fire escape is so out of the ordinary, that its presence already pops this shot.  Then seeing three alcoves that obviously used to be windows is another odd element.  The two together, makes for a visually stimulating shot.  Thank you.', '2008-04-01 23:23:07.000000', NULL, 1),
(4604158, 660319, 90658, '<td valign="top">A little flat for me, but art speaks differently to different people.</td>', 'A little flat for me, but art speaks differently to different people.', '2008-04-01 23:23:47.000000', NULL, 1),
(4604160, 661902, 90658, '<td valign="top">Would a different colored background work better?  Play around and see.</td>', 'Would a different colored background work better?  Play around and see.', '2008-04-01 23:24:24.000000', NULL, 1),
(4604162, 661770, 90658, '<td valign="top">The colors would be more impactful if they were brighter.</td>', 'The colors would be more impactful if they were brighter.', '2008-04-01 23:25:20.000000', NULL, 1),
(4604166, 660461, 90658, '<td valign="top">Almost gives me vertigo! :)  The green plants peaking through add a bit of humor as well as softness to the harsh angles of the building.</td>', 'Almost gives me vertigo! :)  The green plants peaking through add a bit of humor as well as softness to the harsh angles of the building.', '2008-04-01 23:26:23.000000', NULL, 1),
(4604171, 662255, 90658, '<td valign="top">Interesting choice capturing the tail as opposed to the head.  The effect actually adds to the creepiness, imo.  I find myself looking around for the dangerous end.</td>', 'Interesting choice capturing the tail as opposed to the head.  The effect actually adds to the creepiness, imo.  I find myself looking around for the dangerous end.', '2008-04-01 23:27:43.000000', NULL, 1),
(4604173, 661223, 90658, '<td valign="top">Clever design.</td>', 'Clever design.', '2008-04-01 23:28:14.000000', NULL, 1),
(4604176, 661611, 90658, '<td valign="top">The waxy quality of these flowers adds a nice dimension.  You will probably get comments about the colors, but I think that you have done a good job.</td>', 'The waxy quality of these flowers adds a nice dimension.  You will probably get comments about the colors, but I think that you have done a good job.', '2008-04-01 23:29:31.000000', NULL, 1),
(4604179, 662023, 90658, '<td valign="top">Ahh, the humble pineapple.  So univiting on the outside, but such a heart of gold.</td>', 'Ahh, the humble pineapple.  So univiting on the outside, but such a heart of gold.', '2008-04-01 23:30:08.000000', NULL, 1),
(4604184, 661160, 90658, '<td valign="top">This must have taken forever to set-up.  Very creative intrepratation of the challeng.</td>', 'This must have taken forever to set-up.  Very creative intrepratation of the challeng.', '2008-04-01 23:30:51.000000', NULL, 1),
(4604202, 660880, 90658, '<td valign="top">Different take on the building balcony theme.  This one has some interest to it, thank you.</td>', 'Different take on the building balcony theme.  This one has some interest to it, thank you.', '2008-04-01 23:36:08.000000', NULL, 1),
(4604205, 660667, 67258, '<td valign="top">A very strong image, with good use of the single pedestrian in the composition.  I do wonder if you might have been better cropping at the apex of the window, thus reducing the slightly weaker exposed area at the top of the frame?</td>', 'A very strong image, with good use of the single pedestrian in the composition.  I do wonder if you might have been better cropping at the apex of the window, thus reducing the slightly weaker exposed area at the top of the frame?', '2008-04-01 23:36:18.000000', NULL, 1),
(4604207, 661647, 90658, '<td valign="top">Interesting idea.  Was this sunset or sunrise?</td>', 'Interesting idea.  Was this sunset or sunrise?', '2008-04-01 23:36:57.000000', NULL, 1),
(4604208, 661639, 67258, '<td valign="top">Perfect for the challenge, and a wonderful photo in its own right.  In my personal top three.</td>', 'Perfect for the challenge, and a wonderful photo in its own right.  In my personal top three.', '2008-04-01 23:37:03.000000', NULL, 1),
(4604210, 661660, 90658, '<td valign="top">I had trouble finding a defined pattern, but I will give you the benefit of the doubt on this one.  This is well framed and has quite a bit of interest.</td>', 'I had trouble finding a defined pattern, but I will give you the benefit of the doubt on this one.  This is well framed and has quite a bit of interest.', '2008-04-01 23:38:32.000000', NULL, 1),
(4604211, 660634, 67258, '<td valign="top">Superbly observed.  I would be interested to see a version with a little more contrast in the mono conversion (but I may still prefer this one...), nonetheless, a 10 from me.</td>', 'Superbly observed.  I would be interested to see a version with a little more contrast in the mono conversion (but I may still prefer this one...), nonetheless, a 10 from me.', '2008-04-01 23:38:36.000000', NULL, 1),
(4604214, 661849, 90658, '<td valign="top">Probably not as interesting in daylight, huh?</td>', 'Probably not as interesting in daylight, huh?', '2008-04-01 23:39:03.000000', NULL, 1),
(4604217, 662053, 90658, '<td valign="top">I get and appreciate what you attempted to do here, but I found it flat.  Just laying out items of plaid clothing one on top another does not add much dimension.  By making it more of a jumble you would have added shading/lighting/texture and visual interest.</td>', 'I get and appreciate what you attempted to do here, but I found it flat.  Just laying out items of plaid clothing one on top another does not add much dimension.  By making it more of a jumble you would have added shading/lighting/texture and visual interest.', '2008-04-01 23:40:44.000000', NULL, 1),
(4604218, 662159, 90658, '<td valign="top">Interesting idea.  How many times did the stacks fall over?</td>', 'Interesting idea.  How many times did the stacks fall over?', '2008-04-01 23:41:17.000000', NULL, 1),
(4604223, 660978, 90658, '<td valign="top">These candies are so muted that by putting them on a white background, they get even more diminished.  Just a thought.</td>', 'These candies are so muted that by putting them on a white background, they get even more diminished.  Just a thought.', '2008-04-01 23:42:09.000000', NULL, 1),
(4604224, 660645, 90658, '<td valign="top">Simple and refined.</td>', 'Simple and refined.', '2008-04-01 23:42:37.000000', NULL, 1),
(4604226, 662162, 90658, '<td valign="top">There seem to be some hairs or scratches on the surface collecting the water.</td>', 'There seem to be some hairs or scratches on the surface collecting the water.', '2008-04-01 23:43:18.000000', NULL, 1),
(4604230, 660884, 90658, '<td valign="top">These are very pretty eggs.  They are certainly not your ordinary Easter Eggs.</td>', 'These are very pretty eggs.  They are certainly not your ordinary Easter Eggs.', '2008-04-01 23:44:07.000000', NULL, 1),
(4604234, 661598, 90658, '<td valign="top">Is the pattern in the rays of the sun?  Or the mountain peak/reflection.  The subtlty of this makes it hard to fit into the challenge, for my overly tired brain.  But the shot itself is magnificent.</td>', 'Is the pattern in the rays of the sun?  Or the mountain peak/reflection.  The subtlty of this makes it hard to fit into the challenge, for my overly tired brain.  But the shot itself is magnificent.', '2008-04-01 23:45:10.000000', NULL, 1),
(4604239, 660658, 90658, '<td valign="top">A little more cropping so that the point in the upper left corner is right on the border of the shot.</td>', 'A little more cropping so that the point in the upper left corner is right on the border of the shot.', '2008-04-01 23:45:58.000000', NULL, 1),
(4604240, 661684, 67258, '<td valign="top">This is superb - the strong dynamic diagonal composition is what first impresses, and then the placement of the ''actors'' within the frame, which could not be bettered if you had stage managed it!  The lines leading the eye around the frame mean that the viewer lingers, discovering more and more visual treats.  I love the ambiguity of the title - pedestrian as a noun or as an adjective?  For me, the title concentrates my mind on the individual crossing the road - what intrigues me is his head-bowed shadow.  So much to see and enjoy - one for my favourites, to return to again and again.</td>', 'This is superb - the strong dynamic diagonal composition is what first impresses, and then the placement of the ''actors'' within the frame, which could not be bettered if you had stage managed it!  The lines leading the eye around the frame mean that the viewer lingers, discovering more and more visual treats.  I love the ambiguity of the title - pedestrian as a noun or as an adjective?  For me, the title concentrates my mind on the individual crossing the road - what intrigues me is his head-bowed shadow.  So much to see and enjoy - one for my favourites, to return to again and again.', '2008-04-01 23:46:40.000000', NULL, 1),
(4604244, 661231, 90658, '<td valign="top">This is a gorgeous building with a magnificence all its own.  You have captured the grandeur of the architecture, the massiveness of the columns and the fantastic atonality in the color scheme.  Thank you.</td>', 'This is a gorgeous building with a magnificence all its own.  You have captured the grandeur of the architecture, the massiveness of the columns and the fantastic atonality in the color scheme.  Thank you.', '2008-04-01 23:47:11.000000', NULL, 1),
