(4605392, 661923, 89494, '<td valign="top">e cea mai buna poza de departe ...</td>', 'e cea mai buna poza de departe ...', '2008-04-02 04:42:47.000000', NULL, 0),
(4605410, 662177, 83080, '<td valign="top">Wow, this is one of the most under rated photos I''ve seen so far.  The composition is excellent.  The turtle is following the rule of thirds like he/she was trained to be there.  The hand helps scale this picture well and the fingers also make some nice lines through the shot.  Creamy bokeh.  The only small adjustment I might suggest would be turning the turtle (&amp; camera) slightly counter clockwise to lighten the shadows of the neck/shoulder area.  If people can''t see patterns in a turtle then they might need new lenses. :P<br/> <br/>I love this shot and my wife REALLY REALLY loves this shot (the turtle is SO cute).  Thanks for entering it.<br/> <br/></td>', 'Wow, this is one of the most under rated photos I''ve seen so far.  The composition is excellent.  The turtle is following the rule of thirds like he/she was trained to be there.  The hand helps scale this picture well and the fingers also make some nice lines through the shot.  Creamy bokeh.  The only small adjustment I might suggest would be turning the turtle (& camera) slightly counter clockwise to lighten the shadows of the neck/shoulder area.  If people can''t see patterns in a turtle then they might need new lenses. :P I love this shot and my wife REALLY REALLY loves this shot (the turtle is SO cute).  Thanks for entering it. ', '2008-04-02 04:51:54.000000', NULL, 0),
(4605415, 661959, 70514, '<td valign="top">The colors and lighting are so pretty and subtle.  I really enjoy the filling of the frame you composed.  Very nicely done.</td>', 'The colors and lighting are so pretty and subtle.  I really enjoy the filling of the frame you composed.  Very nicely done.', '2008-04-02 04:55:42.000000', NULL, 0),
(4605417, 662137, 80608, '<td valign="top">Congrats on your 4th!<br/></td>', 'Congrats on your 4th!', '2008-04-02 04:56:41.000000', NULL, 0);
