(4605623, 662183, 7810, '<td valign="top">Congrats on the ribbon and the new PB!</td>', 'Congrats on the ribbon and the new PB!', '2008-04-02 06:31:42.000000', NULL, 0),
(4605636, 661917, 30982, '<td valign="top">I thought this was very good for the challenge.  Excellent job with the exposure to keep from overexposing the pink, and excellent detail in the veins of the unopened flower, and the green petals at the base.  Nice!!</td>', 'I thought this was very good for the challenge.  Excellent job with the exposure to keep from overexposing the pink, and excellent detail in the veins of the unopened flower, and the green petals at the base.  Nice!!', '2008-04-02 06:38:16.000000', NULL, 0),
