(4605671, 662137, 23478, '<td valign="top">congrats on the 4th place - I really like the diagonal and the choice of colors.</td>', 'congrats on the 4th place - I really like the diagonal and the choice of colors.', '2008-04-02 06:57:24.000000', NULL, 0),
(4605675, 661925, 30982, '<td valign="top">It''s been too long since I''ve studied math with any care, but I appreciated the title.  I''ve always wondered what fractals found in nature might look like.  As a challenge shot, it lacks enough "subject" for the average voter, even in this contest.  On the technical front, there''s a bit of the blue fringing on my uberbright work monitor that may have put off the technical voters.  From an out of the box standpoint, it''s a very cool take on the challenge!</td>', 'It''s been too long since I''ve studied math with any care, but I appreciated the title.  I''ve always wondered what fractals found in nature might look like.  As a challenge shot, it lacks enough "subject" for the average voter, even in this contest.  On the technical front, there''s a bit of the blue fringing on my uberbright work monitor that may have put off the technical voters.  From an out of the box standpoint, it''s a very cool take on the challenge!', '2008-04-02 07:00:32.000000', NULL, 0),
(4605677, 660658, 80608, '<td valign="top">To anyone who is interested, <br/>This place is the Singapore Esplanade.<br/> <br/>And yes, it is the same building with Andrewt picture( at 6th place)</td>', 'To anyone who is interested, This place is the Singapore Esplanade. And yes, it is the same building with Andrewt picture( at 6th place)', '2008-04-02 07:02:17.000000', NULL, 0),
(4605682, 660880, 23478, '<td valign="top">my favorite in the top 10!</td>', 'my favorite in the top 10!', '2008-04-02 07:03:51.000000', NULL, 0),
